const fs = require('fs');
const html = fs.readFileSync('index.html','utf8');
const script = html.split('<script>')[1].split('</script>')[0];
const ctxStub = new Proxy({}, { get: (t,p) => (p==='createRadialGradient') ? (()=>({addColorStop(){}})) : (()=>{}) });
const canvasStub = { width:720, height:720, getContext:()=>ctxStub };
const documentStub = { getElementById: ()=>canvasStub };
const windowStub = {};
new Function('document','window','performance','requestAnimationFrame', script)(documentStub, windowStub, {now:()=>0}, ()=>{});
const bench = windowStub.__bench;
function edgeViolation(s) {
  const {cx,cy,radius,angle} = s.poly;
  let worst = -Infinity;
  for (const b of s.balls) {
    for (let i=0;i<9;i++){
      const a1 = angle + i*2*Math.PI/9, a2 = angle + (i+1)*2*Math.PI/9;
      const ax = cx+radius*Math.cos(a1), ay = cy+radius*Math.sin(a1);
      const bx = cx+radius*Math.cos(a2), by = cy+radius*Math.sin(a2);
      let nx = -(by-ay), ny = (bx-ax);
      if ((cx-ax)*nx + (cy-ay)*ny < 0){ nx=-nx; ny=-ny; }
      const d = (b.x-ax)*nx + (b.y-ay)*ny;
      if (d > worst) worst = d;
    }
  }
  return worst - 14;
}
function maxOverlap(s) {
  let m = 0;
  for (let i=0;i<s.balls.length;i++) for (let j=i+1;j<s.balls.length;j++){
    const a=s.balls[i], b=s.balls[j];
    const d = Math.hypot(a.x-b.x,a.y-b.y);
    m = Math.max(m, a.r+b.r-d);
  }
  return m;
}
let worstWall = -Infinity, worstBalls = 0;
for (let i=0;i<5400;i++){
  bench.step(1/60);
  const s = bench.getState();
  worstWall = Math.max(worstWall, edgeViolation(s));
  worstBalls = Math.max(worstBalls, maxOverlap(s));
}
console.log('max wall violation (neg=inside ok):', worstWall.toExponential(3));
console.log('max ball-ball overlap (neg=ok):', worstBalls.toExponential(3));
console.log('t:', bench.getState().t);
"

